import json,re,statistics
from pathlib import Path
root=Path('tmp/strata-router-eight-20261004')
ratios={mode:{} for mode in (1,2,3)}
for math in ('fast','conservative'):
 text=(root/'results'/('native-'+math+'-47.log')).read_text()
 for tokens in (512,4096):
  pairs={}
  for n,pair,mode,seconds in re.findall(r'ROUTER_TILES_TIME tokens=(\d+) pair=(\d+) mode=(\d+) seconds=([0-9.]+)',text):
   if int(n)==tokens:pairs.setdefault(int(pair),{})[int(mode)]=float(seconds)
  assert len(pairs)==7 and all(set(v)=={0,1,2,3} and min(v.values())>0 for v in pairs.values())
  for mode in (1,2,3):
   ratio=statistics.median(v[0]/v[mode] for v in pairs.values())
   ratios[mode][math+'-'+str(tokens)]=ratio
   print('ROUTER_SHAPE_NATIVE_GATE',math,tokens,mode,ratio,flush=True)
(root/'native-ratios.json').write_text(json.dumps(ratios,indent=2)+'\n')
eligible=[m for m,r in ratios.items() if min(r['fast-512'],r['fast-4096'])>=1.05 and min(r['conservative-512'],r['conservative-4096'])>=1.02]
assert eligible,'no router shape passed both native timing gates'
mode=max(eligible,key=lambda m:ratios[m]['fast-4096'])
selected={'mode':mode,'option':{1:'tiles12',2:'tiles8',3:'unroll1'}[mode],'ratios':ratios[mode],'rule':'both fast shapes>=1.05 and conservative>=1.02; choose largest fast4096 gain'}
(root/'selected-native.json').write_text(json.dumps(selected,indent=2)+'\n')
print('ROUTER_SHAPE_SELECTED',json.dumps(selected),flush=True)
